const client = $('Postgres - Find Client').first().json;

const signals = client.qualification_signals || {};

const scoutFields = [
  'trigger_event',
  'visible_problem',
  'goal',
  'stakes',
  'emotional_driver',
  'cost_of_inaction',
  'past_attempts',
  'investment_history',
  'desired_state',
  'readiness'
];

let nextObjective = null;

for (const field of scoutFields) {
  if (!signals[field]) {
    nextObjective = field;
    break;
  }
}

return [
  {
    json: {
      next_objective: nextObjective,
      known_signals: signals,
      current_stage: client.current_stage,
      sub_stage: client.sub_stage
    }
  }
];

const currentSignals =
$('Postgres - Find Client').first().json.qualification_signals || {};

const extracted =
$('Parse Extractor JSON').first().json.new_signals || {};

const merged = { ...currentSignals };

for (const [key, value] of Object.entries(extracted)) {
  if (value !== null) {
    merged[key] = value;
  }
}

return [
  {
    json: {
      qualification_signals: merged
    }
  }
];

const raw = $('Scout Extractor').first().json.output;

const parsed = JSON.parse(raw);

return [
  {
    json: parsed
  }
];
